//! The proof of 004-25's private helpers (checklist point 1): every helper
//! of this port that re-implements a function or an inline rule of its
//! script, and has no corpus-proven library equivalent, is compared here
//! with the SCRIPT's own Python on `data/wp8/c004_25.txt`, generated by
//! `tools/gen_wp8_helpers.py` (which runs the script's definitions, and its
//! inline rules copied with their script:line, under Python 3.10 and
//! 3.13). The helpers: `has_num`, `capnorm`, `lo_of`, the
//! `STMT`, `TYPE_CODE_RE` and `SIZE_MAX_RE` reads, `counter_re` and
//! `max_match`, the per-type tree (`build_tree`, `tile_node`, `size_node`,
//! `entry_nodes`, `cdiv`), and `str.isdigit` over the repertoire.
//! `an_altered_corpus_line_fails_the_proof` shows the comparison is live.

#![allow(dead_code)] // the support is the same in the five WP8 proofs

use super::proof_data::{CASES, INPUTS};
use super::{content, review, tree, types};
use crate::doccheck::Report;
use crate::doccheck::checked;
use crate::doccheck::family004::{Field, fields_of, is_field_table, tables};
use crate::doccheck::text::has_i;

const C159: [&str; 11] = [
    "received", "late", "missing", "marked gap", "other-epoch", "too-early", "duplicates",
    "incomplete reassemblies", "demoted rounds", "interrupted events", "dead",
];

fn field(meaning: &str) -> Field {
    Field { off: 0, bits: 0, maxc: None, ty: String::new(), meaning: meaning.to_string(), valid: String::new() }
}

fn triples(v: Vec<(i128, i128, i128)>) -> J {
    ls(v, |(a, b, c)| J::L(vec![i(a), i(b), i(c)]))
}

fn count(n: usize) -> J {
    i(i128::try_from(n).expect("a count"))
}

/// 004-25's per-type tree, as the generator's `tree_25` runs it.
fn tree_of(t: &str) -> J {
    let mut r = Report::default();
    let ft: Vec<Vec<Field>> = tables(t).iter().filter(|tb| is_field_table(tb.head())).map(|tb| fields_of(Some(tb), "AC1", "t", &mut r)).collect();
    if ft.first().is_none_or(Vec::is_empty) {
        return J::N;
    }
    let (mut root, unused) = tree::build_tree(&ft);
    let first = root.rows[0].f.clone();
    let start = checked::add(checked::mul(first.off, 8), tree::lo_of(&first).unwrap_or_default());
    tree::tile_node(&mut root, start, "t", "AC1", &mut r);
    let rbits = tree::size_node(&mut root, "t", &mut r);
    let sec = checked::add(58, tree::cdiv(rbits, 8));
    let starts: Vec<i128> = root.rows.iter().map(|x| x.start).collect();
    let entries: Vec<i128> = tree::entry_nodes(&root).iter().map(|n| n.size).collect();
    let fails: usize = r.failed_criteria().iter().map(|c| r.of(c).len()).sum();
    J::L(vec![i(sec), count(unused.len()), ls(starts, i), ls(entries, i), count(fails)])
}

fn eval(helper: &str, a: &[A], ins: &[String]) -> J {
    if helper == "isdigit" {
        let A::S(c) = &a[0] else { panic!("a character") };
        return J::B(review::py_isdigit(c.chars().next().expect("one character")));
    }
    let t = ins[a[0].idx()].as_str();
    match helper {
        "has_num" => J::B(review::has_number(t, a[1].int())),
        "capnorm" => s(&review::capnorm(t)),
        "lo_of" => oi(tree::lo_of(&field(t))),
        "statements" => triples(types::statements(t)),
        "type_code" => oi(types::type_code(t)),
        "stated_sizes" => ls(types::stated_sizes(t), i),
        "counter" => {
            let A::S(name) = &a[1] else { panic!("a counter name") };
            J::B(has_i(&content::counter_re(name), t))
        }
        "max_match" => {
            let keys: Vec<String> = C159.iter().map(|c| content::counter_re(c)).collect();
            let texts: Vec<&str> = t.split('\n').collect();
            let (n, owner) = content::max_match(&keys, &texts);
            J::L(vec![count(n), ls(owner, |(k, j)| J::L(vec![count(k), count(j)]))])
        }
        "tree" => tree_of(t),
        other => panic!("no helper {other}"),
    }
}

// ---------------------------------------------------------------- support
// (not every JSON kind or builder is used by every port)
// (each WP8 port carries its own copy: no port imports another; a shared
// corpus-proof reader is reported as missing from the library)

/// A JSON value as Python's `json.dumps(…, ensure_ascii=False,
/// separators=(",", ":"))` writes it.
enum J {
    N,
    B(bool),
    I(i128),
    S(String),
    L(Vec<J>),
}

fn dump(j: &J, out: &mut String) {
    match j {
        J::N => out.push_str("null"),
        J::B(b) => out.push_str(if *b { "true" } else { "false" }),
        J::I(i) => out.push_str(&i.to_string()),
        J::S(s) => {
            out.push('"');
            for c in s.chars() {
                match c {
                    '"' => out.push_str("\\\""),
                    '\\' => out.push_str("\\\\"),
                    '\n' => out.push_str("\\n"),
                    '\r' => out.push_str("\\r"),
                    '\t' => out.push_str("\\t"),
                    '\u{8}' => out.push_str("\\b"),
                    '\u{c}' => out.push_str("\\f"),
                    c if u32::from(c) < 0x20 => out.push_str(&format!("\\u{:04x}", u32::from(c))),
                    c => out.push(c),
                }
            }
            out.push('"');
        }
        J::L(xs) => {
            out.push('[');
            for (k, x) in xs.iter().enumerate() {
                if k > 0 {
                    out.push(',');
                }
                dump(x, out);
            }
            out.push(']');
        }
    }
}

fn js(j: &J) -> String {
    let mut s = String::new();
    dump(j, &mut s);
    s
}

fn s(x: &str) -> J {
    J::S(x.to_string())
}

fn i(x: i128) -> J {
    J::I(x)
}

fn oi(x: Option<i128>) -> J {
    x.map_or(J::N, J::I)
}

fn ls<T>(xs: impl IntoIterator<Item = T>, f: impl Fn(T) -> J) -> J {
    J::L(xs.into_iter().map(f).collect())
}

fn strs(xs: &[String]) -> J {
    ls(xs, |x| s(x))
}

/// A JSON value read back: the arguments of a corpus line (ints and
/// strings in a list) and the input strings.
#[derive(Debug, Clone)]
enum A {
    I(i128),
    S(String),
}

impl A {
    fn int(&self) -> i128 {
        match self {
            A::I(n) => *n,
            A::S(_) => panic!("an integer argument"),
        }
    }

    fn idx(&self) -> usize {
        usize::try_from(self.int()).expect("an index")
    }
}

/// The JSON string starting at `chars[*k]` (a `"`), decoded.
fn jstring(chars: &[char], k: &mut usize) -> String {
    let mut out = String::new();
    *k += 1;
    while chars[*k] != '"' {
        if chars[*k] == '\\' {
            *k += 1;
            match chars[*k] {
                'n' => out.push('\n'),
                'r' => out.push('\r'),
                't' => out.push('\t'),
                'b' => out.push('\u{8}'),
                'f' => out.push('\u{c}'),
                'u' => {
                    let hex = |k: usize| -> u32 {
                        let h: String = chars[k..k + 4].iter().collect();
                        u32::from_str_radix(&h, 16).expect("hex")
                    };
                    let mut cp = hex(*k + 1);
                    *k += 4;
                    if (0xD800..0xDC00).contains(&cp) {
                        let lo = hex(*k + 3);
                        cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                        *k += 6;
                    }
                    out.push(char::from_u32(cp).expect("a code point"));
                }
                c => out.push(c),
            }
        } else {
            out.push(chars[*k]);
        }
        *k += 1;
    }
    *k += 1;
    out
}

/// `[1,"x",-3]`.
fn args(text: &str) -> Vec<A> {
    let chars: Vec<char> = text.chars().collect();
    let (mut out, mut k) = (Vec::new(), 1);
    while k < chars.len() && chars[k] != ']' {
        match chars[k] {
            ',' => k += 1,
            '"' => out.push(A::S(jstring(&chars, &mut k))),
            _ => {
                let start = k;
                while chars[k] != ',' && chars[k] != ']' {
                    k += 1;
                }
                let n: String = chars[start..k].iter().collect();
                out.push(A::I(crate::doccheck::pycompat::parse_int(&n).expect("an integer")));
            }
        }
    }
    out
}

/// (cases compared, cases skipped as `big` or `raises:`, mismatches).
fn mismatches(cases: &[(&str, &str, &str)]) -> (usize, usize, Vec<String>) {
    let ins: Vec<String> = INPUTS.iter().map(|t| (*t).to_string()).collect();
    let (mut n, mut skipped, mut bad) = (0, 0, Vec::new());
    for &(helper, a, want) in cases {
        if want == "big" || want.starts_with("raises:") {
            skipped += 1;
            continue;
        }
        n += 1;
        let a = args(a);
        let got = js(&eval(helper, &a, &ins));
        if got != want {
            let shown: Vec<String> = a
                .iter()
                .map(|x| match x {
                    A::I(v) => format!("{v} ({:?})", usize::try_from(*v).ok().and_then(|k| ins.get(k)).map(|t| t.chars().take(160).collect::<String>())),
                    A::S(t) => format!("{t:?}"),
                })
                .collect();
            bad.push(format!("{helper} {shown:?}: script {want}, port {got}"));
        }
    }
    (n, skipped, bad)
}

#[test]
fn private_helpers_equal_the_scripts_own_functions() {
    let (n, skipped, bad) = mismatches(CASES);
    assert!(bad.is_empty(), "{} of {n} differ:\n{}", bad.len(), bad[..bad.len().min(20)].join("\n"));
    assert!(n > 1000 && skipped * 10 < n, "{n} compared, {skipped} skipped");
}

#[test]
fn an_altered_corpus_line_fails_the_proof() {
    let k = CASES.iter().position(|c| c.2 != "big" && !c.2.starts_with("raises:")).expect("a case");
    let mut altered = CASES.to_vec();
    altered[k].2 = "\"altered\"";
    let (_, _, bad) = mismatches(&altered);
    assert_eq!(bad.len(), 1, "the altered case must be the one mismatch: {bad:?}");
}
